def cfgload(p):
    r=tomllib.loads(Path(p).read_text())
    def dur(v):
        if isinstance(v,int): return v*1000
        m=re.fullmatch(r'(\d+)(ms|s|m|h)',v); return int(m[1])*{'ms':1,'s':1000,'m':60000,'h':3600000}[m[2]]
    return dict(locales=r['locales'],default=r['default_locale'],ign=set(r['ignore_params']),routes={k:(dur(v['ttl']),v.get('vary',[])) for k,v in r['routes'].items()})
def neg(h,loc,default):
    rs=[]
    for i,part in enumerate((h or '').split(',')):
        bits=[b.strip() for b in part.split(';')]
        tag=bits[0].lower()
        if not tag: continue
        q=1.0
        for b in bits[1:]:
            if b.lower().startswith('q='):
                try: q=float(b[2:])
                except: q=0
        if q>0: rs.append((-q,i,tag))
    for _,_,t in sorted(rs):
        if t=='*': return default
