        if n=='q': v=re.sub(r'\s+',' ',v.lower().strip())
        kept.append((n,v))
    kept.sort()
    l=neg(lang,c['locales'],c['default']) if 'Accept-Language' in c['routes'][route][1] else ''
    return (route,ident,'&'.join(f'{n}={v}' for n,v in kept),l)
